'use strict';
const fs=require('node:fs/promises'),path=require('node:path');
const core=require('./core.cjs'),native=require('./native-client.cjs'),style=require('./player-style.cjs'),wearables=require('./wearables.cjs'),features=require('./features.cjs');
async function ensureNative(ctx,instance,directory,share=false){core.assert(instance.loader==='fabric'&&native.VERSIONS.includes(instance.minecraft),'The in-game wardrobe supports Fabric 26.3, 1.21.11, 1.21.1 and 1.20.1.');const installed=await features.installFeatures(ctx.catalog(),instance,directory,['localcosmetics','cosmetics','emotes','skin3d',...(share?['cosmeticsharing']:[])],await ctx.listContent(instance.id));core.assert(!installed.skipped.length,installed.skipped.map(s=>s.reason).join(' '));await native.install(directory,path.join(ctx.assets,'..'));return installed;}
async function equipWearable(ctx,p,item,bytes){const {instance,directory}=await ctx.getInstance(p.instanceId);ctx.editable(instance.id);await ensureNative(ctx,instance,directory);await native.prepare(directory,path.join(ctx.assets,'..'),p.username);await native.selectCosmetic(directory,item,bytes);return {name:item.name,username:p.username,type:item.type,instructions:'Equipped '+item.name+'. Restart Minecraft, then use F9 to change slots. Sharing requires CPM on the server and receiving Boralances clients. Enable outer skin layers.'};}
async function registerExpansion(ctx){const {handle,task,data,cloud,assets,dialog,win}=ctx;
 handle('vanilla-list',async()=>{const versions=await ctx.worker('versions');return native.VERSIONS.map(minecraft=>({id:minecraft,minecraft,loader:'vanilla',available:versions.some(v=>v.id===minecraft),name:'Vanilla '+minecraft}));});
 handle('vanilla-install',p=>task('Installing vanilla Minecraft',async()=>{core.assert(native.VERSIONS.includes(p.id),'Choose a listed vanilla version.');const instance=await ctx.createInstance({name:String(p.name||'Vanilla '+p.id),minecraft:p.id,loader:'vanilla',loaderVersion:''});await ctx.installGame(instance.id);return {instance:await ctx.getInstance(instance.id).then(r=>r.instance)};}));
 handle('wardrobe-settings',async p=>{const {directory}=await ctx.getInstance(p.instanceId);return native.outfit(directory);});
 handle('wardrobe-configure',p=>task('Saving outfit preferences',async()=>{ctx.editable(p.instanceId);const {directory}=await ctx.getInstance(p.instanceId);return native.configure(directory,p);}));
 handle('sharing-install',p=>task('Installing shared wardrobe',async()=>{const {instance,directory}=await ctx.getInstance(p.instanceId);ctx.editable(instance.id);await ensureNative(ctx,instance,directory,true);await native.configure(directory,{shareCosmetics:p.share!==false});return {installed:true,requires:'CPM on the server, and Boralances Client plus CPM on receiving clients'};}));
 handle('sharing-server',p=>task('Saving server cosmetic relay',async()=>{const {instance}=await ctx.getInstance(p.instanceId);core.assert(instance.loader==='fabric','Choose a Fabric instance for this server package.');const versions=await ctx.catalog().versions('modrinth','h1E7sQNL',instance,'mod');const version=versions.find(v=>v.channel==='release')||versions[0];core.assert(version,'CPM has no compatible release for this version.');const file=await ctx.catalog().file('modrinth','h1E7sQNL',version.id),chosen=await dialog.showSaveDialog(win(),{defaultPath:file.name,filters:[{name:'CPM Fabric server mod',extensions:['jar']}]});if(chosen.canceled)return null;await core.download(file.url,chosen.filePath,file.hashes);return {file:chosen.filePath,version:instance.minecraft};}));
 handle('skin-starter',p=>task('Equipping free starter skin',async()=>{const {instance,directory}=await ctx.getInstance(p.instanceId);ctx.editable(instance.id);const username=core.offlineProfile(p.username||ctx.settings().offlineName).name;core.assert(!(await core.readJSON(await core.contained(directory,'boralances-wings.json'),{}))[username],'Restore animated wings before changing the base skin.');await ensureNative(ctx,instance,directory);const bytes=await fs.readFile(path.join(assets,'studio-starter.png'));await style.equipTexture(directory,username,'skin',bytes,p.model||'default');await native.prepare(directory,path.join(assets,'..'),username);return {name:username};}));
 handle('wearable-remove',p=>task('Restoring outfit slot',async()=>{ctx.editable(p.instanceId);const {directory}=await ctx.getInstance(p.instanceId);core.assert(['hat','trinket','dress'].includes(p.slot),'Choose a wearable slot.');return native.configure(directory,{clearSlot:p.slot});}));
 handle('wardrobe-export-skin',p=>task('Exporting styled player skin',async()=>{ctx.editable(p.instanceId);const {directory}=await ctx.getInstance(p.instanceId),username=core.offlineProfile(p.username||ctx.settings().offlineName).name;await native.prepare(directory,path.join(assets,'..'),username);const cfg=await core.readJSON(await core.contained(directory,'config/boralances-client/client.json'),{});let base=await fs.readFile(await core.contained(directory,'config/boralances-client/base-skin.png'));if(cfg.wings){core.assert(/^[A-Za-z0-9_-]{1,128}$/.test(cfg.wings),'Invalid wing ID.');base=await fs.readFile(await core.contained(directory,'config/boralances-client/skins/'+cfg.wings+'.png'));}const layers=[];for(const type of ['Dress','Trinket','Hat']){const slot=wearables.TYPES[type],id=cfg[slot];if(!id)continue;core.assert(/^[A-Za-z0-9_-]{1,128}$/.test(id),'Invalid wearable ID.');const bytes=id==='launcher-'+slot?await fs.readFile(await core.contained(directory,'config/boralances-client/selected-'+slot+'.png')):await ctx.texture(await ctx.entitled(await ctx.product(id)));layers.push({type,bytes});}const output=wearables.compose(base,layers),chosen=await dialog.showSaveDialog(win(),{defaultPath:username+'-Boralances-outfit.png',filters:[{name:'Minecraft player skin',extensions:['png']}]});if(chosen.canceled)return null;await fs.writeFile(chosen.filePath,output);return {file:chosen.filePath,instructions:'You can upload this skin to your owned Minecraft account for universal skin-layer visibility. Custom capes still need the shared client.'};}));
 const admin=()=>core.assert(cloud.public()?.admin,'Use the enrolled owner PC and its matching Admin account.');
 handle('admin-items',async()=>{admin();const items=[];for(const kind of ['servers','featured','cosmetics'])for(const item of Object.values(await cloud.db('public/'+kind)||{}).slice(0,100))try{items.push({kind,item:require('./firebase.cjs').validatePublication(kind,item)});}catch{}return items;});
 handle('admin-delete',p=>task('Unpublishing featured item',async()=>{admin();core.assert(['servers','featured','cosmetics'].includes(p.kind),'Unknown collection.');const id=require('./firebase.cjs').segment(p.id);await cloud.db('public/'+p.kind+'/'+id,'DELETE');return {removed:true};}));
 const draftFile=path.join(data,'admin-draft.json');
 handle('admin-draft-save',async p=>{admin();core.assert(['servers','featured','cosmetics'].includes(p.kind),'Unknown draft collection.');const fields={kind:p.kind};for(const key of ['id','name','description','address','version','provider','type','projectId','cosmeticType'])fields[key]=String(p[key]||'').slice(0,key==='description'?500:128);fields.voucherOnly=!!p.voucherOnly;core.assert(typeof p.texture==='string'&&p.texture.length<100000,'Invalid draft image.');style.validatePNG(Buffer.from(p.texture,'base64'),fields.cosmeticType==='Animated Wings'?'wing':['Skin','Hat','Trinket','Dress'].includes(fields.cosmeticType)?'skin':'cape');fields.texture=p.texture;await core.atomicJSON(draftFile,{value:ctx.encrypt(fields),savedAt:Date.now()});return {saved:true};});
 handle('admin-draft-load',async()=>{admin();const saved=await core.readJSON(draftFile,null);return saved?ctx.decrypt(saved.value):null;});
}
module.exports={registerExpansion,equipWearable,ensureNative};
